"""80 random equivalence cases plus state-dependent operation-level timing."""
import json,statistics,time
from pathlib import Path
import mlx.core as mx
import mlx.nn as nn
import numpy as np
from norm_metal_candidate import norm
root=Path(__file__).parent;checks=[];mx.random.seed(2026)
def plain(x,w):
 xf=x.astype(mx.float32)
 return (xf*mx.rsqrt(mx.mean(xf*xf,axis=-1,keepdims=True)+1e-6)*w).astype(x.dtype)
def gated(x,w,gate):return plain(x,w)*nn.silu(gate.astype(mx.float32)).astype(x.dtype)
for shape in [(1,5120),(4,5120),(1,24,256),(1,48,128)]:
 for seed in range(20):
  x=(mx.random.normal(shape)*(.1+seed)).astype(mx.bfloat16);w=(mx.random.normal((shape[-1],))*.1+1).astype(mx.bfloat16);gate=mx.random.normal(shape).astype(mx.bfloat16)
  for name,original,candidate in [('norm',plain(x,w),norm(x,w)),('gated',gated(x,w,gate),norm(x,w,gate=gate))]:
   mx.eval(original,candidate);a,b=np.asarray(original.astype(mx.float32)),np.asarray(candidate.astype(mx.float32))
   checks.append({'shape':shape,'seed':seed,'function':name,'bitexact':np.array_equal(a,b),'different':int(np.count_nonzero(a!=b)),'max_abs':float(np.max(np.abs(a-b)))})
 summary={'passed_bitexact':all(c['bitexact'] for c in checks),'checks':checks}
 (root/'metal-norm-equivalence.json').write_text(json.dumps(summary,indent=2))
 print(shape,'bitexact so far',sum(c['bitexact'] for c in checks),'/',len(checks),flush=True)
print('different values',sum(c['different'] for c in checks),flush=True)

"""Shapes selecting both original row_looped and row_simple reduction paths."""
import json,statistics,time
from pathlib import Path
import mlx.core as mx
import mlx.nn as nn
import numpy as np
from norm_metal_candidate import norm
root=Path(__file__).parent;checks=[];mx.random.seed(418)
def plain(x,w,zero=False):
 w=1+w if zero else w;xf=x.astype(mx.float32)
 return (xf*mx.rsqrt(mx.mean(xf*xf,axis=-1,keepdims=True)+1e-6)*w).astype(x.dtype)
for shape in [(19,5120),(32,5120),(33,5120),(64,5120),(4,24,256),(19,24,256),(64,48,128),(1,17),(3,257),(2,1024),(2,2048)]:
 for zero in [False,True]:
  x=mx.random.normal(shape).astype(mx.bfloat16);w=(mx.random.normal((shape[-1],))*.1+(0 if zero else 1)).astype(mx.bfloat16);gate=mx.random.normal(shape).astype(mx.bfloat16)
  a=plain(x,w,zero);b=norm(x,w,zero_centered=zero);mx.eval(a,b)
  checks.append({'shape':shape,'zero_centered':zero,'bitexact':np.array_equal(np.asarray(a.astype(mx.float32)),np.asarray(b.astype(mx.float32))),'different':int(mx.sum(a!=b).item())})
  if not zero:
   a=plain(x,w)*nn.silu(gate.astype(mx.float32)).astype(x.dtype);b=norm(x,w,gate=gate);mx.eval(a,b)
   checks.append({'shape':shape,'gated':True,'bitexact':np.array_equal(np.asarray(a.astype(mx.float32)),np.asarray(b.astype(mx.float32))),'different':int(mx.sum(a!=b).item())})
def compiled_plain(x,w):return plain(x,w)
old=mx.compile(compiled_plain,shapeless=True);x=mx.random.normal((1,5120)).astype(mx.bfloat16);w=mx.random.normal((5120,)).astype(mx.bfloat16)
def timed(fn):
 def chain():
  value=x
  for _ in range(160):value=fn(value,w)
  mx.eval(value)
 for _ in range(3):chain()
 samples=[]
 for _ in range(5):
  mx.synchronize();s=time.perf_counter();chain();samples.append(time.perf_counter()-s)
 return samples
before=timed(old);after=timed(norm)
result={'passed_bitexact':all(c['bitexact'] for c in checks),'checks':checks,'160_compilednorm_s':before,'160_faithfulmetalnorm_s':after,'ratio':statistics.median(before)/statistics.median(after)}
(root/'metal-norm-extended.json').write_text(json.dumps(result,indent=2));print('bitexact',sum(c['bitexact'] for c in checks),'/',len(checks),'ratio',result['ratio'],'before',before,'after',after,flush=True)

"""Match MLX0.32.3 FP32 mean row reduction before the original final BF16 cast."""
import mlx.core as mx

SOURCE=r'''
    uint tid = thread_position_in_threadgroup.x;
    uint row = threadgroup_position_in_grid.y;
    uint D = x_shape[x_ndim - 1];
    uint lane = tid % 32;
    uint sg = tid / 32;
    uint nsg = TG / 32;
    threadgroup float sums[32];
    float part = 0.0f;
    for (uint first = tid * 4; first < D; first += TG * 4) {
        for (uint j = 0; j < 4 && first + j < D; j++) {
            float xf = float(x[(size_t)row * D + first + j]);
            float sq = xf * xf;
            part = part + sq;
        }
    }
    float total = metal::simd_sum(part);
    if (nsg > 1) {
        if (lane == 0) sums[sg] = total;
        threadgroup_barrier(mem_flags::mem_threadgroup);
        if (sg == 0) {
            float group_part = lane < nsg ? sums[lane] : 0.0f;
            float final_sum = metal::simd_sum(group_part);
            if (lane == 0) sums[0] = final_sum;
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
        total = sums[0];
    }
    float mean = total * (1.0f / float(D));
    float inv = metal::precise::rsqrt(mean + eps[0]);
    for (uint i = tid; i < D; i += TG) {
        float xf = float(x[(size_t)row * D + i]);
        float wf = float(weight[i]);
        if (ZERO_CENTERED) wf = float(W(1.0f + wf));
        float normalized = xf * inv;
        T weighted = T(normalized * wf);
        if (GATED) {
            float value = float(gate[(size_t)row * D + i]);
            float exp_value = metal::precise::exp(metal::abs(value));
            float sig = 1.0f / (1.0f + exp_value);
            sig = value < 0.0f ? sig : 1.0f - sig;
            T activated = T(value * sig);
            weighted = T(float(weighted) * float(activated));
        }
        output[(size_t)row * D + i] = weighted;
    }
'''
kernel=mx.fast.metal_kernel(name='explicit_norm_row',input_names=['x','weight','gate','eps'],output_names=['output'],source=SOURCE,header='#pragma clang fp contract(off)\n')
EPS_VALUES={}
def norm(x,weight,eps=1e-6,zero_centered=False,gate=None):
 D=x.shape[-1];rows=x.size//D
 tg=32 if D<=512 else (128 if D<=1024 else min(1024,((D+3)//4+31)//32*32))
 gated=gate is not None
 if eps not in EPS_VALUES:EPS_VALUES[eps]=mx.array([eps],mx.float32)
 return kernel(inputs=[x,weight,gate if gated else x,EPS_VALUES[eps]],template=[('T',x.dtype),('W',weight.dtype),('TG',tg),('ZERO_CENTERED',zero_centered),('GATED',gated)],grid=(tg,rows,1),threadgroup=(tg,1,1),output_shapes=[x.shape],output_dtypes=[x.dtype])[0]

"""One loaded model, sequential original/candidate runner correctness comparison."""
import gc, hashlib, importlib.util, json, os, sys, time
from pathlib import Path
root=Path(__file__).parent;sys.path.insert(0,str(root/'original-root'))
import mlx.core as mx
import numpy as np
from tutorial_code.miniengine.engine.llm_engine import LLMEngine
from tutorial_code.miniengine.engine.model_runner import ModelRunner as OriginalRunner
from tutorial_code.miniengine.engine.scheduler import Scheduler
from tutorial_code.miniengine.sampling_params import SamplingParams
from tutorial_code.miniengine.model import layers as original_layers
from tutorial_code.miniengine.model import gdn as original_gdn
from tutorial_code.miniengine.kernels import gdn_metal as original_metal
from resource_snapshot import snapshot, deltas, guard
spec=importlib.util.spec_from_file_location('tutorial_code.miniengine.engine.pipeline_runner',root/'candidate-v4-root/tutorial_code/miniengine/engine/model_runner.py')
module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);CandidateRunner=module.ModelRunner
def load_extra(name,path):
 spec=importlib.util.spec_from_file_location(name,path);module=importlib.util.module_from_spec(spec);sys.modules[name]=module;spec.loader.exec_module(module);return module
candidate_norm=load_extra('tutorial_code.miniengine.kernels.norm_metal',root/'candidate-v4-root/tutorial_code/miniengine/kernels/norm_metal.py')
candidate_layers=load_extra('tutorial_code.miniengine.model.v4_layers',root/'candidate-v4-root/tutorial_code/miniengine/model/layers.py')
candidate_metal=load_extra('candidate_metal',root/'candidate-v4-root/tutorial_code/miniengine/kernels/gdn_metal.py')
candidate_gdn=load_extra('tutorial_code.miniengine.model.candidate_gdn',root/'candidate-v4-root/tutorial_code/miniengine/model/gdn.py')
original_functions=(original_layers.RMSNorm.__call__,original_layers.GatedRMSNorm.__call__,original_metal.gated_delta_step_metal,original_gdn.GatedDeltaNet._decode)
w=json.loads((root/'workload.json').read_text());resources=[]
def probe(label):
 resources.append(snapshot(label,os.getpid()));deltas(resources)
 (root/'correctness-v4-resources.json').write_text(json.dumps(resources,indent=2));guard(resources)
probe('before-model-launch')
loaded=LLMEngine(w['model_dir'],max_seqs=4,max_len=2048,dtype=mx.bfloat16)
model=loaded.model;mx.synchronize();mx.clear_cache();probe('model-ready')
from functools import partial
for layer in model.layers:
 if not layer.is_attn and hasattr(candidate_gdn, '_decode_prework'):
  net=layer.linear_attn;net._compiled_prework=mx.compile(partial(candidate_gdn._decode_prework,Hk=net.Hk,Hv=net.Hv,Dk=net.Dk,Dv=net.Dv))
def hash_arrays(arrays):
 h=hashlib.sha256()
 for array in arrays:
  value=np.asarray(array.astype(mx.float32));h.update(str(value.shape).encode());h.update(value.tobytes())
 return h.hexdigest()
class RecordingModel:
 def __init__(self):self.calls=[]
 def __getattr__(self,name):return getattr(model,name)
 def __call__(self,ids,ctx,**kwargs):
  lg=model(ids,ctx,**kwargs);self.calls.append((ctx.mode,lg));return lg
def make_engine(runner_type):
 e=LLMEngine.__new__(LLMEngine);e.model=model;e.cfg=loaded.cfg;e.eos_ids=loaded.eos_ids
 e.scheduler=Scheduler(4,2048,512,e.eos_ids);e.requests={};e._counter=0
 rec=RecordingModel();e.runner=runner_type(rec,2048);return e,rec
def exercise(kind,runner_type):
 if runner_type is CandidateRunner:
  original_layers.RMSNorm.__call__=candidate_layers.RMSNorm.__call__
  original_layers.GatedRMSNorm.__call__=candidate_layers.GatedRMSNorm.__call__
  original_metal.gated_delta_step_metal=candidate_metal.gated_delta_step_metal
  original_gdn.GatedDeltaNet._decode=candidate_gdn.GatedDeltaNet._decode
 else:
  original_layers.RMSNorm.__call__,original_layers.GatedRMSNorm.__call__,original_metal.gated_delta_step_metal,original_gdn.GatedDeltaNet._decode=original_functions
 mx.random.seed(413)
 e,rec=make_engine(runner_type);outputs={};states=[];steps=0
 def add(name,prompt,cap=32,stop=()):
  e.add_request(prompt,SamplingParams(max_tokens=cap,temperature=0,ignore_eos=False,stop_token_ids=stop),req_id=name);outputs[name]=[]
 if kind=='fixed33':add('one',w['prompt_ids'],33)
 elif kind=='normal-eos':add('one',w['prompt_ids'],128)
 elif kind=='cross-cache-boundary':add('long',w['prompt_ids']*14,32)
 elif kind=='mixed-lifecycle':
  add('short',w['prompt_ids'],4);add('long',w['prompt_ids'],32);add('stop',w['prompt_ids'],32,(w['continuation_ids'][5],))
 elif kind=='late-chunked-prefill':
  e.scheduler.max_batched_tokens=64;add('existing',w['prompt_ids'],32)
 elif kind in ('mutable-sampling','input-mutation'):add('one',w['prompt_ids'],12)
 while e.has_work():
  produced=e.step();steps+=1
  for rid,t,done in produced:outputs[rid].append(t)
  if e.runner.batch.size and (kind=='fixed33' or steps in (2,4,8,16,24)):
   mx.eval(*e.runner.batch.arrays());states.append({'step':steps,'req_ids':list(e.runner.batch.req_ids),'lens':list(e.runner.batch.lens),'hash':hash_arrays(e.runner.batch.arrays())})
  if kind=='mixed-lifecycle' and steps==3:add('late',w['prompt_ids'],7)
  if kind=='late-chunked-prefill' and steps==3:add('late',w['prompt_ids']*14,7)
  if kind=='mutable-sampling' and steps==3:
   p=e.requests['one'].sampling;p.temperature=.7;p.top_k=20;p.top_p=.85
  if kind=='mutable-sampling' and steps==7 and 'one' in e.requests:
   p=e.requests['one'].sampling;p.temperature=0;p.top_k=0;p.top_p=1
  if kind=='input-mutation' and steps==3:e.requests['one'].output_token_ids[-1]=w['continuation_ids'][10]
 assert not e.requests and not e.runner.staging and e.runner.batch.size==0
 assert getattr(e.runner,'_ahead',None) is None
 # Reuse after complete unload is part of the same request lifecycle check.
 add('reuse',w['prompt_ids'],5)
 while e.has_work():
  for rid,t,_ in e.step():outputs[rid].append(t)
 mx.synchronize()
 calls=[{'mode':mode,'shape':list(lg.shape),'hash':hash_arrays([lg]),'argmax':mx.argmax(lg,axis=-1).tolist()} for mode,lg in rec.calls]
 del e,rec;gc.collect();mx.clear_cache()
 return {'outputs':outputs,'states':states,'calls':calls,'steps':steps}
results=[]
for kind in ['fixed33','normal-eos','mixed-lifecycle','cross-cache-boundary','late-chunked-prefill','mutable-sampling','input-mutation']:
 before=exercise(kind,OriginalRunner);after=exercise(kind,CandidateRunner)
 (root/'correctness-v4-latest-case.json').write_text(json.dumps({'case':kind,'before':before,'after':after},indent=2))
 assert before['outputs']==after['outputs'],(kind,'output mismatch')
 assert before['states']==after['states'],(kind,'cache mismatch')
 # An EOS or admission can discard a correctly computed future; compare fixed33
 # uninterrupted arithmetic exactly and report extra calls in other scenarios.
 if kind=='fixed33':assert before['calls']==after['calls'],(kind,'logit mismatch')
